def canon(obj): return json.dumps(obj,sort_keys=True,separators=(',',':'),allow_nan=False).encode()
def digest(obj): return hashlib.sha256(canon(obj)).hexdigest()
def require(ok,message):
 if not ok: raise ValueError(message)
def dt(s):
 t=datetime.fromisoformat(str(s).replace('Z','+00:00'))
 require(t.tzinfo is not None,'Timestamp needs explicit timezone')
 return t.astimezone(UTC)
def stamp(t): return t.astimezone(UTC).isoformat().replace('+00:00','Z')
def num(v,default=None):
 try:
  f=float(v)
  return f if math.isfinite(f) else default
 except (ValueError,TypeError): return default

def tick(pair):return .001 if pair.endswith('_JPY') else .00001
def mean(xs): return statistics.fmean(xs) if xs else None
def pct(xs,p):
 if not xs:return None
 a=sorted(xs);x=(len(a)-1)*p;i=int(x);j=math.ceil(x)
 return a[i]+(a[j]-a[i])*(x-i)
def progress(**kw):
 with LOCK:STATE.update(kw)
def output_dir():return Path(os.getenv('P32_AUDIT_OUTPUT_DIR',str(Path(tempfile.gettempdir())/'p32_cost_exposure_audit'))).resolve()
def unpack():
 raw=zlib.decompress(base64.b85decode(PAYLOAD_B85))
 require(hashlib.sha256(raw).hexdigest()==PAYLOAD_SHA256,'Embedded reference checksum failed')
