PRIVATE_KEYS={'authorization','token','secret','webhook_secret','accountid','account_id','userid','user_id','requestid','request_id'}
def redact(obj,c):
 if isinstance(obj,dict):return {k:'[REDACTED]' if k.lower() in PRIVATE_KEYS else redact(v,c) for k,v in obj.items()}
 if isinstance(obj,list):return [redact(x,c) for x in obj]
 if isinstance(obj,str):
  for key in ('token','account'):
   if c.get(key):obj=obj.replace(c[key],'[REDACTED]')
 return obj
class NoRedirect(HTTPRedirectHandler):
 def redirect_request(self,*a,**k):return None

class Reader:
 def __init__(self,c,transport=None):
  self.c=c;self.receipts=[];self.transport=transport;self.lock=threading.Lock()
  self.opener=build_opener(NoRedirect())
 def get(self,kind,path,params=None):
  u=urlsplit(path);require(not(u.scheme or u.netloc or u.query or u.fragment) and '..' not in path,'Relative allowlisted GET paths only')
  headers={'Accept':'application/json','Accept-Datetime-Format':'RFC3339','User-Agent':VERSION}
  if kind=='broker':
   a=re.escape(self.c['account']);pair='(?:'+'|'.join(PAIRS)+')'
   allowed=re.fullmatch('/v3/instruments/'+pair+'/candles',path) or re.fullmatch('/v3/accounts/'+a+r'/(?:summary|instruments|transactions|transactions/idrange|trades/[0-9]+)',path)
   require(allowed,'Broker GET path is not allowlisted')
   headers['Authorization']='Bearer '+self.c['token']
  else:
   routes={'executor':('/', '/live-audit-status','/live-trades','/live-signal-history','/live-execution-stats','/live-rejected-outcomes','/live-rejected-outcome-status'), 'probe':('/live-status','/m15-live-status')}
   require(kind in routes and path in routes[kind] and self.c.get(kind),'Service GET path is not allowlisted')
  url=self.c[kind]+path+('?' + urlencode(params) if params else '')
  req=Request(url,headers=headers,method='GET')
  for attempt in range(3):
   started=datetime.now(UTC)
   try:
    if self.transport:data=self.transport(req)
    else:
     with self.opener.open(req,timeout=45) as r:
      raw=r.read(32*1024*1024+1)
     require(len(raw)<=32*1024*1024,'Response exceeds 32MiB');data=json.loads(raw)
    require(isinstance(data,dict),'Expected JSON object')
    with self.lock:self.receipts.append(dict(kind=kind,path=path.replace(self.c['account'],'[ACCOUNT]'),params=params or {},method='GET',received_at_utc=stamp(datetime.now(UTC)),elapsed_seconds=(datetime.now(UTC)-started).total_seconds(),response_sha256=digest(data)))
    return data
   except Exception as e:
    code=e.code if isinstance(e,HTTPError) else None
    safe='HTTP '+str(code) if code else type(e).__name__+': '+str(e)
    with self.lock:self.receipts.append(dict(kind=kind,path=path.replace(self.c['account'],'[ACCOUNT]'),method='GET',attempt=attempt+1,error=redact(safe,self.c)))
    if isinstance(e,ValueError) or code in (400,401,403,404) or attempt==2:raise RuntimeError(kind+' GET '+path.replace(self.c['account'],'[ACCOUNT]')+' failed: '+redact(safe,self.c)) from None
    time.sleep(.5*(attempt+1))


def validate_registry(root,payload):
 require(root.get('current_live_portfolio_version')==PORTFOLIO,'Live portfolio version differs from pinned P32')
 rules=root.get('strategy_rules');require(isinstance(rules,dict) and len(rules)==32,'Expected 32 live strategy rules')
 for row in payload['registry']:
  sid=row['live_sid'];r=rules.get(sid)
  require(isinstance(r,dict),'Missing live strategy '+sid)
  require(r.get('pair')==row['pair'] and r.get('side')==row['side'] and r.get('timeframe')==row['timeframe'],'Rule identity mismatch '+sid)
  require(sorted(float(v) for v in row['rr'].split(';'))==sorted(float(v) for v in r.get('rr',[])),'RR mismatch '+sid)
  require(abs(float(r.get('risk_percent',-1))-float(row['risk_percent']))<1e-10,'Risk mismatch '+sid)
 require(num(root.get('max_adverse_entry_deviation_ticks'))==10,'Expected unchanged 10-tick limit')
 return {'version':PORTFOLIO,'strategy_count':32,'risk_rr_identity':'PASS','tick_limit':10,'root_is_observation_only':True}


def fetch_live(reader,c,payload):
 evidence={};limitations=[]
 evidence['executor_root']=reader.get('executor','/')
 registry=validate_registry(evidence['executor_root'],payload)
 for key,path,params in [
  ('telemetry','/live-audit-status',None),('trades','/live-trades',{'limit':500}),
  ('signals','/live-signal-history',{'limit':500,'since':stamp(LIVE_START)}),
  ('execution','/live-execution-stats',None),('rejected','/live-rejected-outcomes',{'limit':500,'since':stamp(LIVE_START)}),
  ('rejected_status','/live-rejected-outcome-status',None)]:
  try:
   obj=reader.get('executor',path,params)
   require(obj.get('status') in ('success','online'),'Service returned error status for '+key)
   evidence[key]=obj
   if obj.get('more_available') or (key=='trades' and obj.get('count',0)>=500):limitations.append(key+' may be truncated at 500; no complete-history claim')
  except Exception as e:limitations.append(str(e));evidence[key]={'audit_error':str(e)}
 for path in ('/live-status','/m15-live-status'):
  if c.get('probe'):
   try:evidence[path]=reader.get('probe',path)
   except Exception as e:limitations.append(str(e))
 evidence['account_summary']=reader.get('broker','/v3/accounts/'+c['account']+'/summary')
 try:evidence['instruments']=reader.get('broker','/v3/accounts/'+c['account']+'/instruments',{'instruments':','.join(PAIRS)})
 except Exception as e:limitations.append(str(e));evidence['instruments']={'audit_error':str(e)}
 baseline=evidence.get('telemetry',{}).get('baseline_start_utc')
 if baseline:require(abs((dt(baseline)-LIVE_START).total_seconds())<.001,'Telemetry baseline differs from expected reviewed cohort')
 params={'from':stamp(LIVE_START),'to':stamp(c['cutoff']),'pageSize':1000}
 try:
  meta=reader.get('broker','/v3/accounts/'+c['account']+'/transactions',params)
  transactions=[]
  for page in meta.get('pages',[]):
   u=urlsplit(page);expected='/v3/accounts/'+c['account']+'/transactions/idrange'
   require(u.scheme=='https' and u.netloc==urlsplit(c['broker']).netloc and not(u.username or u.password or u.fragment) and u.path==expected,'Unexpected transaction-page URL')
   q=parse_qs(u.query);require(set(q)<= {'from','to','type'} and all(len(v)==1 for v in q.values()),'Unexpected transaction-page query')
   transactions.extend(reader.get('broker',u.path,{k:v[0] for k,v in q.items()}).get('transactions',[]))
  unique={str(t['id']):t for t in transactions}
  require(len(unique)==len(transactions),'Duplicate broker transaction IDs')
  transactions=sorted((t for t in transactions if LIVE_START<=dt(t['time'])<=c['cutoff']),key=lambda t:(dt(t['time']),int(t['id'])))
  require(int(meta.get('count',len(transactions)))==len(transactions),'Transaction page count/cutoff mismatch')
  evidence['transaction_metadata']=meta;evidence['transactions']=transactions
 except Exception as e:limitations.append(str(e));evidence['transactions']=[]
 evidence['collection_finished_at_utc']=stamp(datetime.now(UTC))
 evidence['live_cutoff_utc']=stamp(c['cutoff'])
