def schedules(evidence):
 instruments=evidence.get('instruments',{}).get('instruments',[]);result={}
 for pair in PAIRS:
  source=next((x for x in instruments if x.get('name')==pair),{})
  financing=source.get('financing') or {};native=financing.get('financingDaysOfWeek') or []
  days={x.get('dayOfWeek'):num(x.get('daysCharged')) for x in native}
  valid=bool(native) and all(k in DAYS and v is not None and 0<=v<=10 for k,v in days.items())
  result[pair]={'days':{d:days.get(d,0) for d in DAYS} if valid else dict(DEFAULT_DAYS),'schedule_source':'CURRENT_NATIVE_SCHEDULE' if valid else 'ASSUMED_WEEKDAY_WED3','long_rate':num(financing.get('longRate')),'short_rate':num(financing.get('shortRate'))}
