def boundaries(entry,end,include=False):
 if end<entry:return []
 first=entry.astimezone(NY).date();last=end.astimezone(NY).date();out=[]
 while first<=last:
  t=datetime(first.year,first.month,first.day,17,tzinfo=NY).astimezone(UTC)
  if entry<t<end or (include and entry<=t<=end):out.append(t)
  first+=timedelta(days=1)
 return out

def charge_days(times,schedule):return sum(schedule['days'][DAYS[t.astimezone(NY).weekday()]] for t in times)
def holding_rows(book,sched):
 rows=[]
 for i,r in enumerate(book):
  entry=dt(r['entry']);end=min(dt(r['exit']),HIST_END) if r['exit'] else HIST_END
  seconds=3600 if r['tf']=='H1' else 900
  nominal=boundaries(entry,end);earliest=max(entry,end-timedelta(seconds=seconds)) if r['exit'] else end
  lower=boundaries(entry,earliest);upper=boundaries(entry,end,True)
  hours=(end-entry).total_seconds()/3600
  bucket=next((label for bound,label in ((1,'<1h'),(4,'1-4h'),(12,'4-12h'),(24,'12-24h'),(72,'1-3d'),(168,'3-7d'),(float('inf'),'>=7d')) if hours<bound))
  rows.append(dict(index=i,**r,entry_year=entry.year,entry_era='2005-2009' if entry.year<2010 else '2010-2014' if entry.year<2015 else '2015-2019' if entry.year<2020 else '2020-cutoff',holding_hours=hours,holding_bucket=bucket,closed=bool(r['exit']),rollovers_nominal=len(nominal),rollovers_lower=len(lower),rollovers_upper=len(upper),charged_days_nominal=charge_days(nominal,sched[r['pair']]),charged_days_lower=charge_days(lower,sched[r['pair']]),charged_days_upper=charge_days(upper,sched[r['pair']]),schedule_source=sched[r['pair']]['schedule_source'],timing='NOMINAL_CANDLE_CLOSE'))
