  out.append(dict(zip(fields,key),trades=len(group),closed=len(closed),wins=len(wins),losses=len(losses),win_rate_pct=100*len(wins)/len(closed) if closed else None,price_r_sum=sum(float(r['r']) for r in closed),holding_hours_mean=mean([r['holding_hours'] for r in group]),holding_hours_median=pct([r['holding_hours'] for r in group],.5),holding_hours_p95=pct([r['holding_hours'] for r in group],.95),holding_hours_max=max(r['holding_hours'] for r in group),winner_holding_hours_mean=mean([r['holding_hours'] for r in wins]),loser_holding_hours_mean=mean([r['holding_hours'] for r in losses]),rollover_trade_pct=100*sum(r['rollovers_nominal']>0 for r in group)/len(group),charged_days_nominal=sum(r['charged_days_nominal'] for r in group),timing_uncertain_trades=sum(r['charged_days_upper']!=r['charged_days_lower'] for r in group)))
