def exposure(sim,book,forced_pairs,non_hedging):
 active={};rows=[];conflicts=[]
 for e in sim['events']:
  i=e['source_record_index'];r=book[i]
  if e['event']=='EXIT':active.pop(i)
  else:
   same=[(j,t) for j,(_,t) in active.items() if t['sid']==r['sid']]
   opp=[(j,t) for j,(_,t) in active.items() if t['pair']==r['pair'] and t['side']!=r['side']]
   for j,t in same+opp:
    gated=t['sid']==r['sid'] or r['pair'] in forced_pairs or non_hedging
    conflicts.append(dict(entry=r['entry'],entering_sid=r['sid'],pair=r['pair'],side=r['side'],active_sid=t['sid'],active_exit=t['exit'],same_strategy=t['sid']==r['sid'],opposite_pair=t['side']!=r['side'],would_conflict_under_observed_live_account=gated,coverage='ACCEPTED_BOOK_OVERLAP_ONLY'))
   active[i]=(e['risk_cash'],r)
  signed=defaultdict(float);gross=defaultdict(float)
  for cash,t in active.values():
   base,quote=t['pair'].split('_');direction=1 if t['side']=='BUY' else -1
   for currency,sgn in ((base,direction),(quote,-direction)):signed[currency]+=sgn*cash;gross[currency]+=cash
  rows.append(dict(time=e['time'],sequence=e['event_sequence'],event=e['event'],active_positions=len(active),open_risk_pct=e['open_risk_pct'],balance=e['balance_after'],**{'gross_'+k+'_stop_risk_pct':100*gross[k]/e['balance_after'] for k in CURRENCIES},**{'signed_'+k+'_stop_risk_pct':100*signed[k]/e['balance_after'] for k in CURRENCIES}))
 summary=[];duration=(HIST_END-HIST_START).total_seconds()
 for currency in CURRENCIES:
  gross='gross_'+currency+'_stop_risk_pct';signed='signed_'+currency+'_stop_risk_pct';weighted=weighted_abs=present=0
  for k,r in enumerate(rows):
   end=dt(rows[k+1]['time']) if k+1<len(rows) else HIST_END
   seconds=max(0,(end-dt(r['time'])).total_seconds())
