def month_keys():
 y,m=HIST_START.year,HIST_START.month;keys=[]
 while (y,m)<(HIST_END.year,HIST_END.month):
  keys.append(f'{y:04}-{m:02}');m+=1
  if m==13:y+=1;m=1
