def correlation_reports(book):
 months=month_keys();sids=sorted({r['sid'] for r in book});vectors={s:{m:0.0 for m in months} for s in sids};entrydays={s:set() for s in sids}
 for r in book:
  entrydays[r['sid']].add(r['entry'][:10])
  if r['exit'] and r['exit'][:7] in vectors[r['sid']]:vectors[r['sid']][r['exit'][:7]]+=float(r['r'])
