  am=mean(a);bm=mean(b);av=sum((x-am)**2 for x in a);bv=sum((x-bm)**2 for x in b)
  return sum((x-am)*(y-bm) for x,y in zip(a,b))/math.sqrt(av*bv) if av>0 and bv>0 else None
