 for a,b in itertools.combinations(sids,2):
  av=[vectors[a][m] for m in months];bv=[vectors[b][m] for m in months];union=entrydays[a]|entrydays[b]
  pairs.append(dict(sid_a=a,sid_b=b,complete_months=len(months),zero_inclusive_monthly_r_correlation=corr(av,bv),shared_losing_months=sum(x<0 and y<0 for x,y in zip(av,bv)),same_entry_day_jaccard=len(entrydays[a]&entrydays[b])/len(union) if union else None,descriptive_only=True))
