  entry=dt(r['entry']);end=dt(r['exit']) if r['exit'] else HIST_END
  require(HIST_START<=entry<HIST_END and end>entry,'Cost overlay record outside frozen historical window or invalid chronology')
  schedule.append((entry,1,r['sid'],i,'ENTRY',0.0))
  g=geometry[i];extra=extra_ticks*tick(r['pair'])/g['stop_distance']
  rate=-annual_rate if rate_mode=='ADVERSE_FLAT' else sched[r['pair']]['long_rate' if r['side']=='BUY' else 'short_rate']
  require(rate is not None,'Current native financing rate missing')
  for t in boundaries(entry,min(end,HIST_END)):
   value=g['notional_to_stop_risk_ratio']*rate/365*sched[r['pair']]['days'][DAYS[t.astimezone(NY).weekday()]]
   if value:schedule.append((t,2,r['sid'],i,'FUNDING',value));financing_by_index[i]+=value
  if r['exit'] and end<=HIST_END:
   schedule.append((end,0,r['sid'],i,'EXIT',float(r['r'])-extra));spread_r+=extra;total_r+=float(r['r'])-extra+financing_by_index[i]
  finance_r+=financing_by_index[i]
