  conversion=sum(x['conversion_costs']) if conversion_complete else None
  financing=x['daily_financing']+x['close_financing']
  reported=num(r.get('financing'));reconciled=reported is not None and abs(financing-reported)<=.00011
  entry=dt(x['entry_time'] or s['logged_at']);end=dt(r['close_time']);sign=1 if s['side']=='BUY' else -1
  ref=num(s.get('reference_entry'));fill=num(s.get('actual_fill'));preview=num(s.get('live_price'));stop=num(s.get('stop'));distance=abs(ref-stop) if ref is not None and stop is not None else None
