  rates.append(dict(basis=basis,kind=kind,hypothetical_wins=w,hypothetical_losses=l,hypothetical_unresolved=unresolved,hypothetical_resolved_win_rate_pct=100*w/(w+l) if w+l else None,actual_closed_trades=n,actual_wins=aw,combined_resolved_denominator=n+w+l,combined_resolved_win_rate_pct=100*(aw+w)/(n+w+l) if n+w+l else None,complete_observed_cohort=unresolved==0 and not evidence.get('rejected',{}).get('more_available',False),hypothetical_cash_or_r_added_to_actual_returns=False))
